begin;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;if actual<>code then raise exception 'FAIL expected %, got %: %',code,actual,q;end if;return;end;raise exception 'FAIL expected rejection: %',q;end;$$;
insert into auth.users(id) values('a6000000-0000-4000-8000-000000000001'),('a6000000-0000-4000-8000-000000000002');
create function pg_temp.refpath() returns text language sql as $$select 'a6000000-0000-4000-8000-000000000001/references/a6000000-0000-4000-8000-000000000003/a6000000-0000-4000-8000-000000000004.jpg'$$;
create function pg_temp.probe(meta jsonb) returns void language sql as $$insert into storage.objects(bucket_id,name,metadata) values('request-reference-images',pg_temp.refpath(),meta)$$;
create function pg_temp.submit() returns public.tailoring_requests language sql as $$select public.send_tailoring_request_with_references('a6000000-0000-4000-8000-000000000005','50000000-0000-4000-8000-000000000002','dress','Keep this optional reference image.',1,current_date+30,false,null,null,'[{"id":"a6000000-0000-4000-8000-000000000004","note":"Use this neckline"}]','a6000000-0000-4000-8000-000000000003')$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.initialize_tailor_profile();
select public.save_tailor_profile('{"shop_name":"Review Atelier","description":"Bespoke garments for special occasions.","specialties":"Dresses","city":"Colombo","public_address":"123 Public Street","business_phone":"+94112223344","years_experience":5,"accepting_requests":true}',true,1);
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000001',true);
select public.reserve_request_reference('a6000000-0000-4000-8000-000000000004','a6000000-0000-4000-8000-000000000003','jpg');
select pg_temp.assert_true(not public.valid_reference_file(pg_temp.refpath(),'{"contentLength":100,"mimetype":"image/jpeg"}'),'021 final-file validator cannot authorize the preliminary probe');
savepoint preliminary;
select pg_temp.probe('{"contentLength":5242880,"mimetype":"image/jpeg"}');
select pg_temp.assert_true(not public.request_reference_ready('a6000000-0000-4000-8000-000000000004'),'preliminary metadata alone cannot count as a completed file');
select pg_temp.expect_error('select pg_temp.submit()','22023');
rollback to savepoint preliminary;release savepoint preliminary;
select pg_temp.expect_error($q$select pg_temp.probe('{"contentLength":0,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$select pg_temp.probe('{"contentLength":5242881,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$select pg_temp.probe('{"contentLength":100,"size":5242881,"mimetype":"image/jpeg"}')$q$,'42501');
select pg_temp.expect_error($q$select pg_temp.probe('{"contentLength":100,"mimetype":"image/png"}')$q$,'42501');
select pg_temp.expect_error($q$select pg_temp.probe('{"mimetype":"image/jpeg"}')$q$,'42501');
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error($q$select pg_temp.probe('{"contentLength":100,"mimetype":"image/jpeg"}')$q$,'42501');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error($q$select pg_temp.probe('{"contentLength":100,"mimetype":"image/jpeg"}')$q$,'42501');
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000001',true);
select pg_temp.probe('{"size":100,"mimetype":"image/jpeg"}');
select pg_temp.submit();select pg_temp.submit();
delete from storage.objects where bucket_id='request-reference-images';
update storage.objects set metadata='{"size":200,"mimetype":"image/jpeg"}' where bucket_id='request-reference-images';
select pg_temp.assert_true((select count(*)=1 and bool_and(metadata->>'size'='100') from storage.objects where bucket_id='request-reference-images'),'snapshot file cannot be deleted or replaced');
select pg_temp.assert_true((select count(*)=1 from public.request_image_references),'snapshot retry remains idempotent');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='request-reference-images'),'addressed tailor sees submitted reference');
select set_config('request.jwt.claim.sub','a6000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-reference-images'),'other customer cannot read/sign reference');
reset role;rollback;
select 'PASS: reference preflight metadata correction, final-file snapshot validation, ownership and immutable retry' as result;
